"""Saved original on-structure speed measurement; no legal verdict."""
import argparse
import json
import math
from pathlib import Path

MPH_PER_MPS=2.2369362921


def measure(history_path,context_path):
    rows=[json.loads(line) for line in Path(history_path).read_text().splitlines()]
    context=json.loads(Path(context_path).read_text())
    if len(rows)!=600 or [r['video_frame'] for r in rows]!=list(range(600)):
        raise ValueError('missing original 600-frame bridge history')
    if not all(rows[i]['native_frame']<rows[i+1]['native_frame'] for i in range(599)):
        raise ValueError('nonmonotonic original Native frames')
    if not all(abs(r['time_s']-i/20)<.005 for i,r in enumerate(rows)):
        raise ValueError('original 20 Hz timing missing')
    if not context.get('native_bridge_survey') or len(context.get('native_sign_survey',[]))!=2:
        raise ValueError('Native bridge or sign survey missing')
    if context.get('bridge_x_m')!=[0.0,100.0] or context.get('sign_limit_mph')!=25.0:
        raise ValueError('structural boundary or sign value missing')
    if len({r.get('subject_id') for r in rows})!=1 or rows[0].get('subject_id') is None:
        raise ValueError('original subject identity missing')
    on=[];speed=[]
    for r in rows:
        pos=r.get('position_xyz_m');vel=r.get('velocity_xyz_mps')
        if not isinstance(pos,list) or len(pos)!=3 or not all(type(v) in (int,float) and math.isfinite(v) for v in pos):
            raise ValueError('original position missing')
        if not isinstance(vel,list) or len(vel)!=3 or not all(type(v) in (int,float) and math.isfinite(v) for v in vel):
            raise ValueError('original velocity missing')
        on.append(0<=pos[0]<=100 and pos[2]>=6)
        speed.append(math.sqrt(sum(v*v for v in vel))*MPH_PER_MPS)
    on_speeds=[v for flag,v in zip(on,speed) if flag]
    if not on_speeds:raise ValueError('no original elevated-structure occupancy')
    return {'frames':600,'on_structure_frames':len(on_speeds),
            'maximum_on_structure_mph':max(on_speeds),
            'on_structure_samples_above_posted_maximum':sum(v>25 for v in on_speeds),
            'posted_maximum_mph':25.0,'department_determination_verified':False,
            'physical_sign_pixels_verified':False,'legal_conclusion':None,
            'physical_review_required':True}


if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--history',required=True);p.add_argument('--context',required=True)
    a=p.parse_args();print(json.dumps(measure(a.history,a.context),sort_keys=True))

import json
from pathlib import Path
import tempfile
import unittest
from geometry import check as geometry_check, open_drive
from runner import check as runner_check, survey, validate_attempt_destination, TARGET_MPS
from finalize import finalize


class FakeCarla:
    class LaneType:
        Driving='driving'
    class Location:
        def __init__(self,x,y,z):self.x,self.y,self.z=x,y,z


class FakeWaypoint:
    def __init__(self,x,y,z):
        self.road_id=1;self.lane_id=-1
        self.transform=type('T',(),{'location':FakeCarla.Location(x,y,z)})()


class FakeMap:
    def __init__(self,wrong_sign=False):self.wrong_sign=wrong_sign
    def to_opendrive(self):
        return open_drive().replace('value="25"','value="35"') if self.wrong_sign else open_drive()
    def get_waypoint(self,location,project_to_road,lane_type):
        z=8 if 0<=location.x<=100 else 0
        return FakeWaypoint(location.x,location.y,z)


class FakeWorld:
    def __init__(self,wrong_sign=False):self.mapping=FakeMap(wrong_sign)
    def get_map(self):return self.mapping


class NativeDraft(unittest.TestCase):
    def test_geometry(self):
        g=geometry_check();self.assertEqual(g['posting_distance_m'],30.48)
        self.assertEqual(g['sign_limit_mph'],25)

    def test_capture_plan(self):
        p=runner_check();self.assertEqual(p['frames'],600)
        self.assertEqual(len(p['cameras']),4)
        self.assertFalse(p['physical_acceptance_claimed'])

    def test_exact_comparison_changes_speed_only(self):
        config=json.loads(Path('config.json').read_text())
        case=config['case_id'].rsplit('__',1)[-1]
        self.assertEqual(config['requested_speed_mps'],TARGET_MPS[case])
        self.assertEqual(config['supported_case_ids'],[
            config['case_id'].rsplit('__',1)[0]+'__probe_01',
            config['case_id'].rsplit('__',1)[0]+'__probe_02'])
        self.assertEqual(config['duration_s'],30)
        self.assertEqual(config['rate_hz'],20)
        self.assertEqual(config['cameras'][0]['name'],'overview')

    def test_materialized_destination_and_replay_rejection(self):
        with tempfile.TemporaryDirectory() as tmp:
            folder=Path(tmp)
            self.assertEqual(validate_attempt_destination(folder),folder.resolve())
            (folder/'bridge-speed-history.jsonl').write_text('original')
            with self.assertRaisesRegex(ValueError,'already exists'):
                validate_attempt_destination(folder)

    def test_saved_finalizer_requires_original_source(self):
        with tempfile.TemporaryDirectory() as tmp:
            attempt=Path(tmp)/'attempt'
            attempt.mkdir()
            with self.assertRaisesRegex(ValueError,'Missing required source: bridge-speed-history.jsonl'):
                finalize(attempt,Path(tmp)/'report.json')

    def test_survey_gate(self):
        self.assertEqual(len(survey(FakeWorld(),FakeCarla)['bridge']),5)
        with self.assertRaisesRegex(RuntimeError,'sign readback differs'):
            survey(FakeWorld(wrong_sign=True),FakeCarla)
